#error "Assertions must remain enabled."
#endif
#include <array>
#include <cassert>
#include <iostream>
// 장비0,1,2의 비용은2,3,4. 두 슬롯과 총예산6.
class Loadout{
    std::array<int,2> slots_{{-1,-1}};
    static int cost(int id){const int c[]={2,3,4};return id<0?0:c[id];}
public:
    bool equip(int slot,int id){
        if(slot<0 || slot>=2 || id< -1 || id>2)return false;
        auto next=slots_;next[slot]=id;
        if(cost(next[0])+cost(next[1])>6)return false;
        slots_=next;return true;
    }
    int get(int slot)const{return slots_.at(slot);}
    int total()const{return cost(slots_[0])+cost(slots_[1]);}
};
int main(){
    Loadout l;assert(l.equip(0,0));assert(l.equip(1,2));assert(l.total()==6);
    assert(!l.equip(0,1));assert(l.get(0)==0 && l.total()==6);
    assert(l.equip(1,-1));assert(l.equip(0,1));assert(l.equip(1,1));
    assert(l.total()==6);assert(!l.equip(2,0));assert(!l.equip(0,3));
    assert(l.get(0)==1 && l.get(1)==1);
    std::cout<<"loadout budget tests passed\n";
}
